import bisect

class Solution:
    def minOperations(self, nums: List[int], x: int, k: int) -> int:
        n = len(nums)

        def cost_to_make_equal(arr):
            arr.sort()
            mid = arr[len(arr) // 2]
            return sum(abs(num - mid) for num in arr)

        def min_cost_for_k_subarrays(starts):
            return sum(cost_to_make_equal(nums[start:start + x]) for start in starts)

        def find_min_cost():
            dp = [[float('inf')] * (k + 1) for _ in range(n)]
            prefix_costs = [0] * n

            for i in range(n):
                if i < x:
                    prefix_costs[i] = cost_to_make_equal(nums[:i + 1])
                else:
                    prefix_costs[i] = prefix_costs[i - x] + cost_to_make_equal(nums[i - x + 1:i + 1])
                dp[i][1] = prefix_costs[i]

            for j in range(2, k + 1):
                for i in range(j * x - 1, n):
                    for l in range((j - 1) * x - 1, i - x + 1):
                        dp[i][j] = min(dp[i][j], dp[l][j - 1] + cost_to_make_equal(nums[l + 1:i + 1]))

            return dp[n - 1][k]

        return find_min_cost()
