from typing import List
from functools import lru_cache

class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        @lru_cache(None)
        def dp(index, current_sum, is_even):
            if index == len(nums):
                return 1 if current_sum == k else float('-inf')

            # Skip the current number
            max_product = dp(index + 1, current_sum, is_even)

            # Include the current number
            if is_even:
                new_sum = current_sum + nums[index]
            else:
                new_sum = current_sum - nums[index]

            if abs(new_sum) <= abs(k):
                product_with_current = nums[index] * dp(index + 1, new_sum, not is_even)
                if product_with_current <= limit:
                    max_product = max(max_product, product_with_current)

            return max_product

        result = dp(0, 0, True)
        return result if result != float('-inf') else -1
