class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        def count_valid_subarrays_without_pair(pair_to_remove):
            # Create a set of all conflicting pairs except the one to remove
            active_conflicts = {tuple(sorted(p)) for p in conflictingPairs if p != pair_to_remove}

            # Initialize variables to track the current segment of valid subarrays
            start = 0
            max_subarrays = 0

            # Iterate through the array from 1 to n
            for i in range(1, n + 1):
                # Check if the current element forms a conflict with any element in the current segment
                for j in range(start, i):
                    if (i, j + 1) in active_conflicts or (j + 1, i) in active_conflicts:
                        # If a conflict is found, count subarrays up to this point and reset start
                        max_subarrays += (i - start) * (i - start + 1) // 2
                        start = i
                        break

            # Count subarrays for the last segment
            max_subarrays += (n - start + 1) * (n - start + 2) // 2

            return max_subarrays

        # Calculate the maximum number of subarrays by removing each pair one by one
        return max(count_valid_subarrays_without_pair(pair) for pair in conflictingPairs)
